                    "Reference": [
                      "Cosmetic Ingredient Review; Final Report of the Cosmetic Ingredient Review Expert Panel; Final Report on the Safety Assessment of Oleic Acid, Lauric Acid, Palmitic Acid, Myristic Acid, and Stearic Acid; p. 51, June  2005."
                    ],
                    "ExtendedReference": [
                      {
                        "Citation": "Cosmetic Ingredient Review; Final Report of the Cosmetic Ingredient Review Expert Panel; Final Report on the Safety Assessment of Oleic Acid, Lauric Acid, Palmitic Acid, Myristic Acid, and Stearic Acid; p. 51, June  2005.",
                        "Matched": {
                          "PCLID": 900158736,
                          "Citation": "Cosmetic Ingredient Review; Final Report of the Cosmetic Ingredient Review Expert Panel; Final Report on the Safety Assessment of Oleic Acid, Lauric Acid, Palmitic Acid, Myristic Acid, and Stearic Acid; p. 51, June  2005."
                        }
                      }
                    ],
                    "Value": {
                      "StringWithMarkup": [
                        {
                          "String": "Several bar soap formulations with concentrations of Myristic Acid of 10, 22.1, and 91% were tested for skin irritation using 16 human subjects. A 0.2 mL volume of an 8% aqueous preparation was applied to the ventral skin of the forearm under occlusive patches once daily for 5 days using the Frosch-Kligman soap chamber test. The formulations were considered \"slightly\" to \"moderately irritating\" and erythema scores were 1.41, 1.73, and 1.95 on a scale of 0 to 5 for the formulations containing 10, 22.1, and 91% myristic acid, respectively.",
                          "Markup": [
                            {
                              "Start": 53,
                              "Length": 13,
                              "URL": "https://pubchem.ncbi.nlm.nih.gov/compound/Myristic%20Acid",
